    border-radius:4px;padding:8px 10px;backdrop-filter:blur(2px)}
  #topleft{position:absolute;top:14px;left:14px;min-width:210px}
  .row{display:flex;justify-content:space-between;gap:14px;font-size:13px;line-height:1.55}
  .lbl{color:#5f8ba8;letter-spacing:1px}
  .val{color:#00e5ff;text-shadow:0 0 8px rgba(0,229,255,.6);font-weight:bold}
  .val.mag{color:#ff5fd2;text-shadow:0 0 8px rgba(255,95,210,.6)}
  .val.warn{color:#ffd23f;text-shadow:0 0 8px rgba(255,210,63,.6)}
  #buffs{position:absolute;left:14px;bottom:14px;min-width:210px;font-size:12px}
  .buff{display:flex;justify-content:space-between;gap:10px;line-height:1.5}
  .buff.off{opacity:.32}
  #minimapWrap{position:absolute;right:14px;bottom:14px}
  #minimap{display:block;border:1px solid rgba(0,229,255,.28);border-radius:4px;
    background:rgba(4,10,20,.75)}
  #mmLabel{text-align:center;font-size:10px;color:#5f8ba8;letter-spacing:2px;margin-top:4px}
  #title{position:absolute;top:14px;left:50%;transform:translateX(-50%);text-align:center}
  #title h1{font-size:14px;letter-spacing:5px;color:#00e5ff;text-shadow:0 0 12px rgba(0,229,255,.7)}
  #title .sub{font-size:10px;letter-spacing:3px;color:#5f8ba8;margin-top:2px}
  #modebar{position:absolute;top:64px;left:50%;transform:translateX(-50%);
    font-size:11px;letter-spacing:3px;color:#ff5fd2;text-shadow:0 0 10px rgba(255,95,210,.6)}
  #bossbar{position:absolute;top:88px;left:50%;transform:translateX(-50%);width:min(520px,60vw);display:none}
  #bossbar .name{font-size:10px;letter-spacing:3px;color:#ff6b6b;margin-bottom:3px;text-align:center}
  #bossbar .track{height:9px;border:1px solid rgba(255,107,107,.5);border-radius:3px;overflow:hidden;
    background:rgba(30,0,0,.5)}
  #bossbar .fill{height:100%;width:100%;background:linear-gradient(90deg,#ff2d55,#ff9f43);
    box-shadow:0 0 12px rgba(255,45,85,.8);transition:width .12s linear}
  #multbar{position:absolute;top:50%;left:50%;transform:translate(-50%,120px);width:190px;display:none}
  #multbar .lbl2{font-size:9px;letter-spacing:2px;color:#5f8ba8;text-align:center;margin-bottom:2px}
  #multbar .track{height:4px;border:1px solid rgba(0,229,255,.35);overflow:hidden;border-radius:2px}
  #multbar .fill{height:100%;background:#00e5ff;box-shadow:0 0 10px #00e5ff;width:0%}
  #crosshair{position:absolute;top:50%;left:50%;width:22px;height:22px;transform:translate(-50%,-50%);
    opacity:.55}
  #crosshair:before,#crosshair:after{content:"";position:absolute;background:#00e5ff;box-shadow:0 0 6px #00e5ff}
  #crosshair:before{left:50%;top:0;width:1px;height:100%;transform:translateX(-50%)}
  #crosshair:after{top:50%;left:0;height:1px;width:100%;transform:translateY(-50%)}
  #feed{position:absolute;right:14px;top:120px;width:230px;text-align:right;font-size:11px}
  .feedline{opacity:.9;margin-bottom:2px;text-shadow:0 0 6px currentColor}
  .feedline.ok{color:#5cff9d}.feedline.err{color:#ff5f6d}
  #chat{position:absolute;left:14px;bottom:120px;width:330px;z-index:30;pointer-events:auto;
    background:rgba(6,14,26,.9);border:1px solid rgba(0,229,255,.28);border-radius:4px;
    display:flex;flex-direction:column;font-size:11px;overflow:hidden}
  #chat header{display:flex;align-items:center;gap:8px;padding:5px 8px;background:rgba(0,229,255,.08);
    border-bottom:1px solid rgba(0,229,255,.2);cursor:pointer}
  #chat header .t{letter-spacing:2px;color:#00e5ff}
  #chat header .badge{margin-left:auto;font-size:9px;padding:2px 6px;border-radius:8px;letter-spacing:1px}
  .badge.sim{background:rgba(255,210,63,.18);color:#ffd23f}
  .badge.tw{background:rgba(255,95,210,.18);color:#ff5fd2}
  .badge.off{background:rgba(120,140,160,.18);color:#7f96aa}
  #chatBody{display:flex;flex-direction:column;height:224px}
  #msgs{flex:1;overflow-y:auto;padding:6px 8px;line-height:1.5;scrollbar-width:thin}
  #msgs .u{color:#7fd7ff}
  #msgs .m{color:#cfe9f7;word-break:break-word}
  #msgs .ok .m{color:#5cff9d}
  #msgs .err .m{color:#ff5f6d}
  #msgs .sys{color:#5f8ba8;font-style:italic}
  .chatrow{display:flex;gap:4px;padding:5px 6px;border-top:1px solid rgba(0,229,255,.14)}
  .chatrow.hide{display:none}
  #chat input[type=text]{flex:1;min-width:0;background:rgba(0,0,0,.45);border:1px solid rgba(0,229,255,.25);
    color:#bfefff;font-family:inherit;font-size:11px;padding:4px 6px;border-radius:3px;outline:none}
  #chat input[type=text]:focus{border-color:#00e5ff}
  #chat button{background:rgba(0,229,255,.14);border:1px solid rgba(0,229,255,.4);color:#00e5ff;
    font-family:inherit;font-size:10px;letter-spacing:1px;padding:4px 8px;border-radius:3px;cursor:pointer}
  #chat button:hover{background:rgba(0,229,255,.3)}
  #chat.collapsed #chatBody{display:none}
  .screen{position:fixed;inset:0;z-index:40;display:flex;align-items:center;justify-content:center;
    background:radial-gradient(circle at 50% 45%,rgba(8,20,40,.9),rgba(2,4,10,.97))}
  .screen .box{width:min(720px,92vw);text-align:center;padding:26px;border:1px solid rgba(0,229,255,.25);
    border-radius:6px;background:rgba(6,14,26,.7)}
  .screen h2{font-size:22px;letter-spacing:6px;color:#00e5ff;text-shadow:0 0 16px rgba(0,229,255,.6)}
  .screen p{font-size:12px;line-height:1.9;color:#9fc6dc;margin:12px 0}
  .screen .keys{font-size:11px;color:#7fd7ff;line-height:2;text-align:left;display:inline-block;margin:8px auto}
  .screen .keys b{color:#ffd23f}
  .screen button{margin-top:10px;background:linear-gradient(180deg,rgba(0,229,255,.25),rgba(0,229,255,.08));
    border:1px solid #00e5ff;color:#eafcff;font-family:inherit;font-size:12px;letter-spacing:3px;
    padding:10px 26px;border-radius:4px;cursor:pointer;text-shadow:0 0 8px rgba(0,229,255,.8)}
  .screen button:hover{background:rgba(0,229,255,.4)}
  .hide{display:none!important}
</style>
</head>
<body>
<canvas id="c"></canvas>

<div id="hud">
  <div id="title" class="panel">
    <h1>ASTEROIDS SURVIVOR</h1>
    <div class="sub">TWITCH ARENA PROTOCOL</div>
  </div>

  <div id="topleft" class="panel">
    <div class="row"><span class="lbl">SCORE</span><span class="val" id="uiScore">0</span></div>
    <div class="row"><span class="lbl">MULT</span><span class="val mag" id="uiMult">x1</span></div>
    <div class="row"><span class="lbl">LIVES</span><span class="val warn" id="uiLives">III</span></div>
    <div class="row"><span class="lbl">LEVEL</span><span class="val" id="uiLevel">1</span></div>
    <div class="row"><span class="lbl">ROCKS</span><span class="val" id="uiRocks">0</span></div>
  </div>

  <div id="modebar"></div>

  <div id="bossbar">
    <div class="name" id="bossName">VOID SENTINEL</div>
    <div class="track"><div class="fill" id="bossFill"></div></div>
  </div>

  <div id="multbar">
    <div class="lbl2">NEXT MULTIPLIER</div>
    <div class="track"><div class="fill" id="multFill"></div></div>
  </div>

  <div id="buffs" class="panel">
    <div class="buff" id="bShield"><span class="lbl">SHIELD</span><span class="val">OFF</span></div>
    <div class="buff" id="bRapid"><span class="lbl">RAPIDFIRE</span><span class="val">OFF</span></div>
    <div class="buff" id="bOver"><span class="lbl">OVERDRIVE</span><span class="val">OFF</span></div>
    <div class="buff" id="bMag"><span class="lbl">MAGNET</span><span class="val">OFF</span></div>
    <div class="buff" id="bDrones"><span class="lbl">DRONES</span><span class="val" id="uiDrones">1</span></div>
  </div>

  <div id="minimapWrap" class="panel">
    <canvas id="minimap" width="176" height="176"></canvas>
    <div id="mmLabel">TACTICAL RADAR</div>
  </div>

  <div id="feed"></div>
  <div id="crosshair"></div>
</div>

<div id="chat">
  <header id="chatHead">
    <span class="t">TWITCH CHAT</span>
    <span class="badge sim" id="chatBadge">SIMULATOR</span>
  </header>
  <div id="chatBody">
    <div id="msgs"></div>
    <div class="chatrow">
      <input type="text" id="connectName" placeholder="twitch channel">
      <input type="text" id="connectAuth" placeholder="oauth:xxx" type="password">
      <button id="connectBtn">CONNECT</button>
    </div>
    <div class="chatrow">
      <input type="text" id="simBtn" value="SIMULATOR" readonly style="max-width:96px">
      <button id="simToggle">TOGGLE SIM</button>
      <input type="text" id="fileChat" placeholder="file:// test message">
      <button id="fileSend">SEND</button>
    </div>
    <div class="chatrow hide" id="tellRow">
      <input type="text" id="tellChat" placeholder="say something to chat">
      <button id="tellSend">TELL</button>
    </div>
  </div>
</div>

<div class="screen" id="startScreen">
  <div class="box">
    <h2>ASTEROIDS SURVIVOR</h2>
    <p>3D zero-G asteroid arena. Every rock splits until it reaches its minimum radius.<br>
       Boss encounters every 5 levels. Chat commands rebuild your fire mode live.</p>
    <div class="keys">
      <b>W / S</b> thrust forward / reverse &nbsp;&nbsp; <b>A / D</b> rotate ship<br>
      <b>Q / E</b> vertical thrust &nbsp;&nbsp; <b>MOUSE / SPACE</b> fire<br>
      <b>1 2 3 4</b> fire mode single / double / triple / swarmer<br>
      <b>P / ESC</b> pause &nbsp;&nbsp; <b>R</b> respawn (when dead)<br>
      <b>!</b> type in the chat panel to run commands
    </div>
    <br>
    <button id="startBtn">LAUNCH</button>
  </div>
</div>

<div class="screen hide" id="pauseScreen">
  <div class="box">
    <h2>PAUSED</h2>
    <p>press P or ESC to resume</p>
  </div>
</div>

<div class="screen hide" id="overScreen">
  <div class="box">
    <h2 id="overTitle">SHIP DESTROYED</h2>
    <p id="overStats"></p>
    <button id="respawnBtn">RESPAWN [R]</button>
  </div>
</div>

<script type="module">
import * as THREE from 'https://unpkg.com/three@0.161.0/build/three.module.js';

const rnd=(a,b)=>a+Math.random()*(b-a);
const rint=(a,b)=>Math.floor(rnd(a,b+1));
const pick=a=>a[Math.floor(Math.random()*a.length)];
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const $=id=>document.getElementById(id);

const MODES=[
  {name:'single',  drones:1, pattern:'center'},
  {name:'double',  drones:2, pattern:'twin'},
  {name:'triple',  drones:3, pattern:'spread'},
  {name:'swarmer', drones:6, pattern:'swarm'}
];
CHUNK1
echo "chunk1 written: $(wc -l < asteroids.html) lines"

