    const m=new THREE.ShaderMaterial({
      vertexShader:`attribute float aSize;attribute vec3 aColor;varying vec3 vC;
        void main(){vC=aColor;vec4 mv=modelViewMatrix*vec4(position,1.0);
        gl_PointSize=aSize*(320.0/max(0.001,-mv.z));gl_Position=projectionMatrix*mv;}`,
      fragmentShader:`varying vec3 vC;
        void main(){vec2 d=gl_PointCoord-0.5;float a=smoothstep(0.5,0.0,length(d));
        if(a<0.01)discard;gl_FragColor=vec4(vC,a);}`,
      transparent:true,depthWrite:false,blending:THREE.AdditiveBlending
    });
