class Pool{
  constructor(factory,n){
    this.items=[];this.factory=factory;
    for(let i=0;i<n;i++){const o=factory();o.alive=false;this.items.push(o);}
  }
  get(){
    for(const o of this.items)if(!o.alive){o.alive=true;o.mesh.visible=true;return o;}
    const o=this.factory();o.alive=true;this.items.push(o);return o;
  }
  each(fn){for(const o of this.items)if(o.alive)fn(o);}
  kill(o){o.alive=false;o.mesh.visible=false;}
}

