function handleChatCommand(user,text){
  if(!S.running&&!S.over)return;
  const clean=String(text).trim();
  if(!clean)return;
  const lower=clean.toLowerCase();
  if(lower.charAt(0)==='!'){
    const parts=lower.slice(1).split(/\s+/);
    const id=parts[0];
    const def=COMMANDS.find(c=>c.id===id);
    if(!def){
      chatLine('err',user,'unknown command: '+clean);
      feed('unknown: '+id,'err');
      twitch.tell('unknown command: '+id);
      return;
    }
    const arg=parts.slice(1).join(' ');
    if(def.args&&!arg){
      chatLine('err',user,'!'+id+' needs a mode name');
      feed('missing arg: '+id,'err');
      return;
    }
    const ok=ACTIONS[id](arg);
    if(ok){
      chatLine('ok',user,clean);
      feed('accepted: '+id,'ok');
      twitch.tell(id+' executed');
    }else{
      chatLine('err',user,clean+' could not be applied');
      feed('rejected: '+id,'err');
      twitch.tell(id+' failed');
    }
    return;
  }
  const modeIndex=MODES.findIndex(m=>m.name===lower);
  if(modeIndex>=0){
    setMode(modeIndex);
    chatLine('ok',user,clean);
    feed('accepted: '+lower,'ok');
    twitch.tell('mode '+lower);
    return;
  }
  chatLine('err',user,clean+' is not a known command');
  feed('rejected: '+lower,'err');
  twitch.tell('unknown: '+lower);
}

