function fire(){
  const origin=S.shipPos;
  const fwd=forwardVector();
  const right=new THREE.Vector3().crossVectors(fwd,new THREE.Vector3(0,1,0)).normalize();
  const mode=MODES[S.mode];
  const shots=[];
  if(S.overdrive>0){
    for(let i=-2;i<=2;i++)shots.push(origin.clone().addScaledVector(fwd,1).addScaledVector(right,i*0.42).addScaledVector(fwd,Math.abs(i)*0.12));
  }else if(mode.pattern==='twin'){
    shots.push(origin.clone().addScaledVector(fwd,1).addScaledVector(right,-0.4));
    shots.push(origin.clone().addScaledVector(fwd,1).addScaledVector(right,0.4));
  }else if(mode.pattern==='spread'){
    shots.push(origin.clone().addScaledVector(fwd,1.1));
    shots.push(origin.clone().addScaledVector(fwd,1).addScaledVector(right,-0.55));
    shots.push(origin.clone().addScaledVector(fwd,1).addScaledVector(right,0.55));
  }else if(mode.pattern==='swarm'){
    for(let i=0;i<4;i++){
      const off=new THREE.Vector3(rnd(-0.7,0.7),rnd(-0.5,0.5),0);
      shots.push(origin.clone().addScaledVector(fwd,1).add(off));
    }
  }else{
    shots.push(origin.clone().addScaledVector(fwd,1.1));
  }
  const speed=38;
  for(const s of shots){
    const b=bullets.get();
    b.mesh.position.copy(s);
    const dir=fwd.clone();
    if(S.overdrive>0&&shots.length>1)dir.addScaledVector(right,(s.clone().sub(origin).dot(right))*0.05).normalize();
    b.vel.copy(dir.multiplyScalar(speed));
    b.life=1.7;
  }
  FX.burst(origin.clone().addScaledVector(fwd,1.2),3,new THREE.Color(0x9dfcff),4,0.5,0.2);
  S.camPos.addScaledVector(fwd,-0.06);
}

function droneFire(d){
  const target=nearestTarget(d.mesh.position,90);
  if(!target)return;
  const b=bullets.get();
  b.mesh.position.copy(d.mesh.position);
  const dir=target.mesh.position.clone().sub(d.mesh.position).normalize();
  b.vel.copy(dir.multiplyScalar(34));
  b.life=1.6;
  d.cd=0.45;
  FX.burst(d.mesh.position,2,new THREE.Color(0x7f9cff),3,0.4,0.15);
}

function nearestTarget(from,maxDist){
  let best=null,bd=maxDist*maxDist;
  for(const r of rocks){
    const d2=r.mesh.position.distanceToSquared(from);
    if(d2<bd){bd=d2;best=r;}
  }
  if(S.boss){
    const d2=S.boss.mesh.position.distanceToSquared(from);
    if(d2<bd)return S.boss;
  }
  return best;
}

