    this.vel[i*3]=v.x;this.vel[i*3+1]=v.y;this.vel[i*3+2]=v.z;
    this.col[i*3]=color.r;this.col[i*3+1]=color.g;this.col[i*3+2]=color.b;
    this.base[i*3]=color.r;this.base[i*3+1]=color.g;this.base[i*3+2]=color.b;
    this.size[i]=size;this.life[i]=life;this.max[i]=life;
    this.drag[i]=drag===undefined?1.2:drag;
  }
  burst(p,count,color,speed,size,life){
    for(let i=0;i<count;i++){
      const d=new THREE.Vector3(rnd(-1,1),rnd(-1,1),rnd(-1,1)).normalize()
