function damageBoss(amount){
  const b=S.boss;
  if(!b)return;
  b.hp-=amount;
  b.flash=0.12;
  FX.burst(b.mesh.position.clone().add(randomPoint(4)),10,new THREE.Color(0xffd23f),6,0.7,0.5);
  if(b.hp<=0){killBoss();return;}
  const pct=b.hp/b.maxHp;
  $('bossFill').style.width=(clamp(pct,0,1)*100).toFixed(1)+'%';
  const np=pct>0.75?0:(pct>0.5?1:(pct>0.25?2:3));
  if(np!==b.phase){
    b.phase=np;
    b.mesh.geometry.dispose();
    b.mesh.geometry=bossGeoBank[np%4].clone();
    b.attackCd=0.9;
    b.enraged=np===3;
    $('bossName').textContent=b.name+' :: PHASE '+(np+1)+(b.enraged?' [ENRAGED]':'');
    FX.burst(b.mesh.position,140,new THREE.Color(0xff2d55),18,1.6,1.2);
    feed('boss phase '+(np+1),'err');
  }
}
function killBoss(){
  const b=S.boss;
  if(!b)return;
  FX.burst(b.mesh.position,240,new THREE.Color(0xff5f6d),22,1.8,1.6);
  FX.burst(b.mesh.position,160,new THREE.Color(0xffd23f),14,1.3,1.4);
  scene.remove(b.mesh);
  b.weak.forEach(w=>scene.remove(w.mesh));
  S.boss=null;
  addScore(5000);
  for(let i=0;i<3;i++)spawnPower(b.mesh.position.clone().add(randomPoint(6)));
  $('bossbar').style.display='none';
  nextLevel();
}
function bossShoot(b,dir,speed,mat){
  const e=enemies.get();
  if(mat)e.mesh.material=mat;else e.mesh.material=enemyMatA;
  e.mesh.position.copy(b.mesh.position);
  e.vel.copy(dir.normalize().multiplyScalar(speed));
  e.life=6;
}

const keys={};
addEventListener('keydown',e=>{
  const k=e.key.toLowerCase();
  if(e.code==='Space'){S.fireHeld=true;e.preventDefault();}
  if(e.code==='KeyP'||k==='escape')togglePause();
  if(k==='r'&&S.over)respawn();
  if(k>='1'&&k<='4')setMode(parseInt(k,10)-1);
  if(document.activeElement&&document.activeElement.tagName==='INPUT')return;
  keys[k]=true;
});
addEventListener('keyup',e=>{
  keys[e.key.toLowerCase()]=false;
  if(e.code==='Space')S.fireHeld=false;
});
