    const a=b.angle*2.2+w.offset+i;
    const wob=Math.sin(t*3+i)*0.35;
    w.mesh.position.copy(b.mesh.position).add(new THREE.Vector3(
      Math.cos(a)*(spinR+wob),Math.sin(a*1.3+b.phase)*0.9,Math.sin(a)*(spinR+wob)));
    w.mesh.rotation.y+=dt*4;
    w.mesh.scale.setScalar(1+Math.sin(t*6+i)*0.12);
    w.mesh.material.emissiveIntensity=1.8+Math.sin(t*7+i)*0.6;
  });

  b.attackCd-=dt*(b.enraged?1.55:1);
  if(b.attackCd>0)return;
  if(b.phase===0){
    b.attackCd=2.3;
    for(let i=0;i<10;i++){
      const a=(i/10)*Math.PI*2+t;
      bossShoot(b,new THREE.Vector3(Math.cos(a),0,Math.sin(a)),13,null);
    }
  }else if(b.phase===1){
    b.attackCd=1.5;
    const aim=S.shipPos.clone().addScaledVector(S.shipVel,0.4).sub(b.mesh.position);
    bossShoot(b,aim,20,null);
    FX.burst(b.mesh.position,10,new THREE.Color(0xff5f6d),8,0.7,0.3);
  }else if(b.phase===2){
    b.attackCd=1.9;
    const aim=S.shipPos.clone().sub(b.mesh.position).normalize();
    const side=new THREE.Vector3().crossVectors(aim,new THREE.Vector3(0,1,0)).normalize();
    for(let i=-1;i<=1;i++)bossShoot(b,aim.clone().addScaledVector(side,i*0.16),19,null);
    if(Math.random()<0.5){
      bossShoot(b,new THREE.Vector3(rnd(-1,1),rnd(-1,1),rnd(-1,1)).normalize(),11,enemyMatB);
    }
  }else{
    b.attackCd=0.34;
    const a=t*4;
    bossShoot(b,new THREE.Vector3(Math.cos(a),Math.sin(a*0.7)*0.4,Math.sin(a)),20,null);
    if(Math.random()<0.2){
      bossShoot(b,S.shipPos.clone().sub(b.mesh.position).normalize(),26,enemyMatC);
    }
  }
}
function updateWeakpoints(){
  const b=S.boss;
  if(!b)return;
  bullets.each(bl=>{
    for(const w of b.weak){
      if(bl.mesh.position.distanceTo(w.mesh.position)<1.1){
        damageBoss(6);
        b.vulnerable=2.0;
        FX.burst(w.mesh.position,26,new THREE.Color(0xffe08a),9,0.9,0.6);
        feed('weakpoint hit','ok');
        bullets.kill(bl);
        return;
      }
    }
  });
}
function updateDrones(dt,t){
  const center=S.shipPos;
  for(let i=0;i<drones.length;i++){
    const d=drones[i];
    d.orbit+=dt*(1.2+i*0.18);
    const a=d.orbit+i*1.1;
    const r=2.6+Math.sin(t*1.5+i)*0.35;
    const want=center.clone().add(new THREE.Vector3(
      Math.cos(a)*r,Math.sin(a*0.8+i)*1.1+0.6,Math.sin(a)*r));
    d.mesh.position.lerp(want,dt*6);
    d.mesh.rotation.y+=dt*3;
    d.cd-=dt;
    if(d.cd<=0){
      const target=nearestTarget(d.mesh.position,70);
      if(target)droneFire(d);
      else d.cd=0.3;
    }
  }
}

function spawnWave(){
  const count=Math.min(9+S.level*2,30);
  for(let i=0;i<count;i++){
    let pos=randomPoint(rnd(35,80));
    if(pos.distanceTo(S.shipPos)<18)pos=randomPoint(80);
    spawnRock(0,pos,rnd(1.0,1.3));
  }
}
function nextLevel(){
  S.level++;
  $('uiLevel').textContent=S.level;
  if(isBossLevel(S.level)){
    spawnBoss();
    feed('level '+S.level+' :: boss level','ok');
  }else{
    spawnWave();
    feed('level '+S.level,'ok');
  }
}

function updateCamera(dt){
  const fwd=forwardVector();
  const desired=S.shipPos.clone().addScaledVector(fwd,-11).add(new THREE.Vector3(0,4.6,0));
  S.camPos.lerp(desired,clamp(dt*4.5,0,1));
  S.camLook.lerp(S.shipPos.clone().addScaledVector(fwd,7),clamp(dt*6,0,1));
  if(S.shake>0){
    S.shake=Math.max(0,S.shake-dt*2.2);
    const k=S.shake*0.9;
    S.camPos.add(new THREE.Vector3(rnd(-k,k),rnd(-k,k),rnd(-k,k)));
  }
  camera.position.copy(S.camPos);
  camera.lookAt(S.camLook);
}
