  const plot=(p,size,color)=>{
    mm.fillStyle=color;
    mm.beginPath();mm.arc(cx+p.x*scale,cy+p.z*scale,size,0,Math.PI*2);mm.fill();
  };
  for(const p of powers)plot(p.mesh.position,2.2,POWER_STYLE[p.id].color);
  for(const r of rocks)plot(r.mesh.position,Math.max(1.4,r.radius*2.2),'#ffb347');
  if(S.boss){
    plot(S.boss.mesh.position,6,'#ff2d55');
    forconst_unused:{}
