  const set=(id,v)=>{
    const e=$(id);
    if(e.lastElementChild.textContent!==v)e.lastElementChild.textContent=v;
  };
  set('bRapid',S.rapid>0?S.rapid.toFixed(1)+'s':'OFF');
  set('bOver',S.overdrive>0?S.overdrive.toFixed(1)+'s':'OFF');
  set('bMag',S.magnet>0?S.magnet.toFixed(1)+'s':'OFF');
  $('bRapid').classList.toggle('off',S.rapid<=0);
  $('bOver').classList.toggle('off',S.overdrive<=0);
  $('bMag').classList.toggle('off',S.magnet<=0);
  const need=10+S.mult*4;
  const prog=1-clamp(S.killsToNext/need,0,1);
  $('multFill').style.width=(prog*100).toFixed(0)+'%';
  $('multbar').style.display=S.mult>=2?'block':'none';
  $('uiRocks').textContent=rocks.length;
