}

const clock=new THREE.Clock();
let t=0;
function animate(){
  requestAnimationFrame(animate);
  const dt=Math.min(clock.getDelta(),0.05);
  t+=dt;
  twitch.update(dt);
  if(S.running&&!S.paused){
    updateShip(dt);
    updateRocks(dt);
    updateBullets(dt);
    updatePowers(dt);
    updateDrones(dt,t);
    updateBoss(dt,t);
    updateWeakpoints();
    S.rapid=Math.max(0,S.rapid-dt);
    S.overdrive=Math.max(0,S.overdrive-dt);
    S.magnet=Math.max(0,S.magnet-dt);
    S.invuln=Math.max(0,S.invuln-dt);
    shipGroup.visible=S.invuln>0?(Math.sin(t*40)>-0.2):true;
    if(!S.boss&&rocks.length===0&&!isBossLevel(S.level))nextLevel();
  }
  FX.update(dt);
  updateCamera(dt);
  updateHud(dt);
  drawMinimap();
  boundary.rotation.y+=dt*0.02;
  renderer.render(scene,camera);
}

function togglePause(){
  if(!S.running)return;
  S.paused=!S.paused;
  $('pauseScreen').classList.toggle('hide',!S.paused);
}

$('startBtn').addEventListener('click',start);
$('respawnBtn').addEventListener('click',respawn);

function start(){
  $('startScreen').classList.add('hide');
  S.running=true;
  S.paused=false;
  S.score=0;S.mult=1;S.lives=3;S.level=1;S.droneExtra=0;
  S.killsToNext=14;S.rapid=0;S.overdrive=0;S.magnet=0;S.shield=false;S.invuln=2.5;
  $('uiScore').textContent='0';
  $('uiMult').textContent='x1';
  $('uiLevel').textContent='1';
  updateLives();
  setMode(0);
  S.shipPos.set(0,0,0);
  S.shipVel.set(0,0,0);
  S.yaw=0;
  S.pitch=0;
  clearRocks();
  spawnWave();
  feed('launch complete','ok');
}
animate();
</script>
</body>
</html>
